sections.content:
.karten {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}
.karte {
  flex: 1 1 200px;
  /* wachsen, schrumpfen,
     Startbreite 200px */
}

.galerie {
  display: grid;
  grid-template-columns:
    repeat(3, 1fr);
  gap: 10px;
}
.galerie .gross {
  grid-column: span 2;
}

img {
  max-width: 100%;
}
.galerie {
  display: grid;
  grid-template-columns: 1fr;
}
@media (min-width: 600px) {
  .galerie {
    grid-template-columns:
      repeat(2, 1fr);
  }
}
@media (min-width: 900px) {
  .galerie {
    grid-template-columns:
      repeat(3, 1fr);
  }
}

/* Ganz ohne Media Query:
   so viele Spalten (mind. 200px)
   wie hineinpassen */
.galerie {
  display: grid;
  gap: 1rem;
  grid-template-columns:
    repeat(auto-fit,
      minmax(200px, 1fr));
}
